// The Generation mode: spacetime generated by a field theory, in five stations (physis decision
// 0006). (1) An action S[φ], its interactions drawn as bubbles. (2) Its perturbative expansion:
// the Feynman graphs at an order, each a coloured graph weighted by N to the number of its
// faces, and the series of Z and log Z. (3) A graph's discrete spacetime: its 2-complex, its
// pseudomanifold, and for a group field theory its spin foam, opened in the complex views.
// (4) The large-N or condensed phase: the eigenvalue density and planar free energy of matrices,
// the melonic resummation of tensors, the gap equation of vectors, the condensate of a group
// field theory with its bounce. (5) The continuum: a random geometry of that phase (a planar
// quadrangulation, a melonic graph) with its spectral and Hausdorff dimensions.
//
// The same five stations serve quantum field theories of every rank (scalar, vector, matrix,
// tensor) and group field theories, as the decision orders them.

import { el, clear } from './dom.js';
import { graphSvg, simplicialVertexSvg } from './graphs.js';
import { xyChart, chartLegend } from './plot.js';
import { renderDimensions } from './dimensions.js';
import { number, polynomialText, superscript } from './format.js';
import { realise } from '../../../visualization/js/index.js';
import { Realisation } from './views/realisation.js';


// The engine's exact coefficients are strings ("746496/5"); numbers are formatted.
const exact = (c, digits) => (typeof c === 'string' ? c : number(c, digits));
const STATIONS = [
  { id: 'action', title: 'The action', what: 'S[φ]: a field, its interactions drawn as bubbles', hands: 'its Feynman rules' },
  { id: 'graphs', title: 'Feynman graphs', what: 'the expansion: coloured graphs, each weighted by N to its number of faces', hands: 'a graph' },
  { id: 'spacetime', title: 'Discrete spacetime', what: 'a graph\'s 2-complex, pseudomanifold, spin foam', hands: 'which graphs dominate' },
  { id: 'large-n', title: 'Large N, condensate', what: 'the phase the dominant graphs make', hands: 'its typical geometry' },
  { id: 'continuum', title: 'The continuum', what: 'a random geometry and its dimensions', hands: 'spacetime' },
];

// What a theory's large-N phase looks like as a geometry.
function continuumOf(theory, params) {
  if (!theory) return null;
  if (theory.id === 'matrix') return { kind: 'quadrangulation', D: 2, expected: { ds: 2, dh: 4, label: '(2D quantum gravity)' } };
  if (theory.rank >= 3 || theory.family === 'GFT') {
    const D = Number(params?.D) || (theory.id === 'gft-ooguri' ? 4 : theory.rank);
    return { kind: 'melonic', D, expected: { ds: 4 / 3, dh: 2, label: '(branched polymers)' } };
  }
  return null;
}

export function mountGeneration({ left, board, api, onOpen, onFoam, status }) {
  const g = {
    theories: null, error: null, theory: null, params: {}, order: 2, connectedOnly: true,
    expansion: null, expanding: false, expandError: null, selected: null,
    large: null, largeError: null, largeLoading: false,
    cond: { G: 1, spins: [{ two_j: 1, Q: 1, E: 0 }], phi: [-1, 1], points: 241 }, condensate: null, condRunning: false, condError: null,
    geo: { size: 400, seed: 1, kind: null, D: 3 }, geometry: null, geoRunning: false, geoError: null,
    dims: null, dimsRunning: false, dimsError: null,
    station: 'action', follow: null,
  };
  const geoHost = el('div', { class: 'gen-view' });
  let geoView = null;

  async function load() {
    try {
      g.theories = (await api.theories()).theories;
      g.error = null;
    } catch (error) { g.error = error.message; }
    renderLeft();
  }

  function choose(id, { order, stage, expand } = {}) {
    const t = g.theories?.find((x) => x.id === id) || g.theories?.[0];
    if (!t) return;
    if (g.theory?.id !== t.id) {
      g.theory = t;
      g.params = Object.fromEntries((t.params || []).map((p) => [p.name, p.default]));
      g.expansion = g.large = g.condensate = g.geometry = g.dims = null;
      g.expanding = g.largeLoading = false;
      g.selected = null;
      const c = continuumOf(t, g.params);
      g.geo.kind = c?.kind ?? null;
      g.geo.D = c?.D ?? 3;
      fetchLarge();
    }
    if (order) g.order = order;
    renderLeft();
    render();
    if (stage) { g.follow = expand ? stage : null; setTimeout(() => goto(stage), 50); }
    if (expand) runExpand();
  }

  // A passage follows its station: once the run it started has answered, the board is
  // scrolled there again (a re-render would otherwise leave it elsewhere).
  function follow() {
    if (!g.follow) return;
    const id = g.follow;
    g.follow = null;
    setTimeout(() => goto(id), 30);
  }

  function goto(id) {
    g.station = id;
    board.querySelector(`#gen-${id}`)?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    for (const b of board.querySelectorAll('.station')) b.classList.toggle('on', b.dataset.id === id);
  }

  // Answers that arrive after the theory has changed are dropped: each request remembers the
  // theory it was made for.
  const current = (t) => g.theory === t;

  async function runExpand() {
    const t = g.theory;
    if (!t) return;
    g.expanding = true; g.expandError = null; render();
    try {
      const answer = await api.expand(t.id, g.params, g.order);
      if (!current(t)) return;
      g.expansion = answer;
      g.selected = null;
    } catch (error) { if (!current(t)) return; g.expandError = error.message; g.expansion = null; }
    g.expanding = false;
    render();
    follow();
  }

  async function fetchLarge() {
    const t = g.theory;
    if (!t) return;
    g.largeLoading = true; g.largeError = null;
    try {
      const answer = await api.largeN(t.id, g.params);
      if (!current(t)) return;
      g.large = answer;
    } catch (error) { if (!current(t)) return; g.large = null; g.largeError = error.message; }
    g.largeLoading = false;
    render();
  }

  async function runCondensate() {
    g.condRunning = true; g.condError = null; render();
    try { g.condensate = await api.condensate({ spins: g.cond.spins, G: g.cond.G, phi: g.cond.phi, points: g.cond.points }); } catch (error) { g.condError = error.message; }
    g.condRunning = false;
    render();
    follow();
  }

  async function runGeometry() {
    const kind = g.geo.kind || 'quadrangulation';
    g.geoRunning = true; g.geoError = null; g.dims = null; render();
    try {
      const answer = await api.randomGeometry({ kind, size: g.geo.size, D: g.geo.D, seed: g.geo.seed });
      g.geometry = answer.complex;
      drawGeometry();
      runDims();
    } catch (error) { g.geoError = error.message; }
    g.geoRunning = false;
    render();
  }

  async function runDims(graph = 'skeleton') {
    if (!g.geometry) return;
    g.dimsRunning = true; g.dimsError = null; render();
    try { g.dims = await api.dimensions(g.geometry, graph); } catch (error) { g.dimsError = error.message; }
    g.dimsRunning = false;
    render();
    follow();
  }

  function drawGeometry() {
    if (!g.geometry) return;
    if (!geoView) geoView = new Realisation(geoHost, {});
    const geometry = realise(g.geometry, { seed: 1, rings: 2 });
    geoView.setNames(g.geometry.edges.map((_, i) => `e${i + 1}`));
    geoView.show(g.geometry, geometry, { vertexSize: 0.6, edgeWidth: 1.4, arrowSize: 0, faceOpacity: 0.45, rings: 2, labels: false, arrows: false, positions: true, seed: 1 }, true);
  }

  // ---- the left column: the theories ---------------------------------------------------------
  function renderLeft() {
    clear(left);
    left.append(el('h3', { text: 'Theories' }));
    if (g.error) { left.append(el('p', { class: 'note pad error', text: g.error })); return; }
    if (!g.theories) { left.append(el('p', { class: 'note pad', text: 'Asking the engine for its theories…' })); return; }
    for (const family of ['QFT', 'GFT']) {
      left.append(el('div', { class: 'family', text: family === 'QFT' ? 'Quantum field theories, by rank' : 'Group field theories' }));
      for (const t of g.theories.filter((x) => x.family === family)) {
        left.append(el('button', { class: `item${g.theory?.id === t.id ? ' selected' : ''}`, onclick: () => choose(t.id) },
          t.title, el('span', { class: 'rank', text: `rank ${t.rank}` })));
      }
    }
    left.append(el('h3', { text: 'Passages' }),
      el('div', { class: 'pad examples' },
        el('button', { class: 'chip', onclick: () => choose('matrix', { order: 2, expand: true, stage: 'graphs' }) }, 'The BIPZ matrix model at order 2'),
        el('button', { class: 'chip', onclick: () => choose('coloured-simplicial', { order: 2, expand: true, stage: 'graphs' }) }, 'Coloured graphs and their degree'),
        el('button', { class: 'chip', onclick: () => choose('gft-boulatov', { order: 2, expand: true, stage: 'graphs' }) }, 'Boulatov\'s GFT and its spin foams'),
        el('button', { class: 'chip', onclick: () => { choose('gft-melonic', { stage: 'large-n' }); g.follow = 'large-n'; runCondensate(); } }, 'A condensate with one spin, and its bounce'),
        el('button', { class: 'chip', onclick: () => { choose('matrix', { stage: 'continuum' }); g.follow = 'continuum'; runGeometry(); } }, 'A random planar quadrangulation')),
      el('p', { class: 'note pad', text: 'Each passage opens the mode at a station; every station can be changed and run again.' }));
  }

  // ---- the board -----------------------------------------------------------------------------
  function render() {
    clear(board);
    board.append(el('div', { class: 'gen-head' },
      el('h2', { text: 'The generation of spacetime' }),
      el('p', { text: 'A field theory\'s perturbative expansion is a sum over graphs; each graph is a discrete spacetime (a surface, a triangulation, a spin foam); the graphs that dominate at large N, or the condensate they form, make a phase; its typical geometry, at large size, is the continuum. Choose a theory on the left and follow the stations.' })));
    const path = el('div', { class: 'stations' });
    STATIONS.forEach((s, i) => {
      path.append(el('button', { class: `station${g.station === s.id ? ' on' : ''}`, dataset: { id: s.id }, onclick: () => goto(s.id) },
        el('span', { class: 'num', text: String(i + 1) }), el('span', { class: 'title', text: s.title }), el('span', { class: 'what', text: s.what }),
        i < STATIONS.length - 1 ? el('span', { class: 'hands', text: `→ ${s.hands}` }) : null));
    });
    board.append(path);
    if (!g.theory) { board.append(el('p', { class: 'note', text: g.theories ? 'Choose a theory.' : '' })); return; }
    board.append(stageAction(), stageGraphs(), stageSpacetime(), stageLarge(), stageContinuum());
  }

  const section = (id, n, title, ...body) => el('section', { id: `gen-${id}`, class: 'stage-card' }, el('h3', {}, el('span', { class: 'num', text: String(n) }), title), ...body);

  function stageAction() {
    const t = g.theory;
    const bubbles = el('div', { class: 'bubbles' });
    if (t.bubbles?.length) {
      for (const b of t.bubbles) bubbles.append(el('figure', {}, graphSvg(b.coloured_graph, { size: 104, propagator: false, title: b.name }), el('figcaption', { text: b.name })));
    } else {
      const k = (Number(g.params.D) || (t.id === 'gft-ooguri' ? 4 : t.rank)) + 1;
      bubbles.append(el('figure', {}, simplicialVertexSvg(k, { size: 132 }), el('figcaption', { text: `the simplicial vertices, ${k} colours: λ ∏ φ_c and λ̄ ∏ φ̄_c` })));
    }
    const fields = (t.params || []).map((p) => {
      const input = p.type === 'text'
        ? el('input', { type: 'text', value: g.params[p.name] ?? p.default ?? '', oninput: () => { g.params[p.name] = input.value; } })
        : el('input', { type: 'number', value: g.params[p.name] ?? p.default, min: p.min, max: p.max, step: p.type === 'int' ? 1 : 'any', oninput: () => { g.params[p.name] = Number(input.value); } });
      return el('label', { class: 'field' }, el('span', { class: 'label', text: p.name === 'group' ? 'group (Z2, Z3, S3, …)' : p.name }), input);
    });
    return section('action', 1, `${t.title}`,
      el('div', { class: 'action-line' }, el('span', { class: `badge ${t.family}` }, t.family), el('span', { class: 'badge' }, `rank ${t.rank}`), el('span', { class: 'action', text: t.action })),
      el('p', { class: 'lead-text', text: t.description }),
      el('div', { class: 'note', text: 'Its interactions, as bubbles: black vertices φ, white vertices φ̄, each index a colour; a propagator will join a φ to a φ̄ (colour 0).' }),
      bubbles,
      fields.length ? el('div', { class: 'grid narrow' }, ...fields) : null,
      el('div', { class: 'row' }, el('button', { class: 'button', onclick: () => { fetchLarge(); goto('large-n'); } }, 'Its large-N phase'),
        el('button', { class: 'button primary', onclick: () => { runExpand(); goto('graphs'); } }, 'Expand it')));
  }

  function stageGraphs() {
    const order = el('input', { type: 'number', min: 1, max: 6, value: g.order, style: 'width: 60px', oninput: () => { g.order = Number(order.value) || 1; } });
    const head = el('div', { class: 'row' }, el('span', { class: 'note', text: 'order in λ' }), order,
      el('label', { class: 'check' }, el('input', { type: 'checkbox', checked: g.connectedOnly ? true : null, onchange: (e) => { g.connectedOnly = e.target.checked; render(); } }), 'connected graphs only'),
      el('button', { class: 'button primary', disabled: g.expanding ? true : null, onclick: runExpand }, g.expanding ? 'Expanding…' : 'Expand'),
      g.expandError ? el('span', { class: 'error', text: g.expandError }) : null);
    const body = [head];
    const x = g.expansion;
    if (x) {
      const shown = x.graphs.filter((gr) => !g.connectedOnly || gr.connected);
      const top = Math.max(...x.graphs.filter((gr) => gr.connected).map((gr) => gr.n_power));
      const rank = g.theory.rank;
      body.push(el('p', { class: 'fact', text: `${number(x.total)} Wick contractions at order ${g.order}, ${x.graphs.length} graphs up to relabelling, ${x.graphs.filter((gr) => gr.connected).length} connected${x.truncated ? ' (truncated)' : ''}. The ones with the highest power of N dominate at large N: ringed in gold.` }));
      // The series.
      const series = el('div', { class: 'series' });
      const line = (name, list) => list?.forEach((s) => series.append(el('div', {}, el('span', { class: 'faint', text: `${name} at λ${superscript(s.order)}: ` }), polynomialText(s.terms))));
      line('Z', x.series?.Z);
      line('log Z', x.series?.F);
      if (x.leading) series.append(el('div', { class: 'leading' }, `leading: ${polynomialText([x.leading])} at order ${g.order}`));
      body.push(series);
      const gallery = el('div', { class: 'gallery' });
      for (const gr of shown.slice(0, 160)) {
        const lead = gr.connected && gr.n_power === top;
        const shape = rank === 2 && gr.genus !== null && gr.genus !== undefined ? `genus ${gr.genus}` : gr.degree !== null && gr.degree !== undefined ? `ω = ${gr.degree}` : gr.connected ? 'connected' : 'disconnected';
        gallery.append(el('button', { class: `card${lead ? ' lead' : ''}${g.selected === gr ? ' on' : ''}`, onclick: () => { g.selected = gr; render(); goto('spacetime'); } },
          graphSvg(gr.coloured_graph, { size: 96, title: gr.id }),
          el('span', { class: 'power', text: `N${superscript(gr.n_power)}` }),
          el('span', { class: 'meta', text: `${shape} · |Aut| ${gr.automorphisms}` }),
          el('span', { class: 'meta', text: `weight ${gr.weight}${gr.amplitude !== null && gr.amplitude !== undefined ? ` · A = ${number(gr.amplitude, 4)}` : ''}` })));
      }
      if (shown.length > 160) gallery.append(el('p', { class: 'note', text: `… and ${shown.length - 160} more.` }));
      body.push(gallery);
    } else if (!g.expanding) body.push(el('p', { class: 'note', text: 'Expand the theory to see its graphs.' }));
    return section('graphs', 2, 'Feynman graphs', ...body);
  }

  function stageSpacetime() {
    const gr = g.selected;
    if (!gr) return section('spacetime', 3, 'Discrete spacetime', el('p', { class: 'note', text: 'Choose a Feynman graph above: each is a discrete spacetime. Its faces (bicoloured cycles) bound the 2-cells of a 2-complex, the dual 2-skeleton of the pseudomanifold the graph encodes; for a group field theory, the spin foam on it is the graph\'s amplitude.' }));
    const cg = gr.coloured_graph;
    const k = cg.colours;
    const open = async (view) => {
      status?.(view === 'pseudomanifold' ? 'Building its pseudomanifold…' : 'Building its 2-complex…');
      try {
        const answer = await api.graphComplex(cg, view);
        const about = view === 'pseudomanifold'
          ? `The ${k - 1}-dimensional pseudomanifold of a Feynman graph of ${g.theory.title} at order ${g.order}: each vertex of the graph a ${k - 1}-simplex, each edge of colour c a gluing of two facets.`
          : `The 2-complex of a Feynman graph of ${g.theory.title} at order ${g.order}: the graph with a 2-cell on each bicoloured cycle (N${superscript(gr.n_power)}).`;
        onOpen(answer.complex, about);
      } catch (error) { status?.(error.message); }
    };
    const explain = k === 4
      ? 'A 4-coloured graph is dual to a 3-dimensional triangulation: each vertex a tetrahedron, each edge a triangle, each face (a bicoloured cycle) an edge. Its spin foam puts a spin on each face and a 6j symbol on each vertex.'
      : k === 3 ? 'A 3-coloured graph is a ribbon graph: its faces are the polygons of a surface whose genus the power of N counts.'
        : k >= 5 ? `A ${k}-coloured graph is dual to a ${k - 1}-dimensional triangulation.` : 'A graph of a rank-0 or rank-1 theory: no faces bound a surface; it is a graph, not yet a geometry.';
    return section('spacetime', 3, 'Discrete spacetime',
      el('div', { class: 'selected-graph' },
        graphSvg(cg, { size: 230, title: gr.id }),
        el('div', {},
          el('dl', { class: 'facts' },
            el('dt', { text: 'colours' }), el('dd', { text: `${k} (colour 0 the propagators)` }),
            el('dt', { text: 'vertices · edges' }), el('dd', { text: `${2 * cg.p} · ${k * cg.p}` }),
            el('dt', { text: 'power of N' }), el('dd', { text: `N${superscript(gr.n_power)}` }),
            gr.genus !== null && gr.genus !== undefined ? el('dt', { text: 'genus' }) : null, gr.genus !== null && gr.genus !== undefined ? el('dd', { text: String(gr.genus) }) : null,
            gr.degree !== null && gr.degree !== undefined ? el('dt', { text: 'Gurau degree' }) : null, gr.degree !== null && gr.degree !== undefined ? el('dd', { text: `ω = ${gr.degree}${gr.degree === 0 ? ', melonic' : ''}` }) : null,
            el('dt', { text: 'weight · |Aut|' }), el('dd', { text: `${gr.weight} · ${gr.automorphisms}` }),
            gr.amplitude !== null && gr.amplitude !== undefined ? el('dt', { text: 'amplitude' }) : null, gr.amplitude !== null && gr.amplitude !== undefined ? el('dd', { text: `${number(gr.amplitude, 6)} (BF theory over ${g.params.group || 'the group'})` }) : null),
          el('p', { class: 'note', text: explain }),
          el('div', { class: 'row' },
            k >= 2 ? el('button', { class: 'button', onclick: () => open('2-complex') }, 'Open its 2-complex') : null,
            k >= 3 ? el('button', { class: 'button', onclick: () => open('pseudomanifold') }, 'Open its pseudomanifold') : null,
            k === 4 ? el('button', { class: 'button primary', onclick: async () => {
              try { const answer = await api.graphComplex(cg, '2-complex'); onFoam(answer.complex, `The spin foam of a Feynman graph of ${g.theory.title}: spins on the faces of its 2-complex, 6j symbols on its vertices.`); } catch (error) { status?.(error.message); }
            } }, 'Its spin foam') : null))));
  }

  function stageLarge() {
    const L = g.large, t = g.theory;
    const body = [];
    if (g.largeLoading) body.push(el('p', { class: 'note', text: 'Solving the large-N phase…' }));
    if (g.largeError) body.push(el('p', { class: 'error', text: g.largeError }));
    if (t.id === 'scalar') body.push(el('p', { class: 'note', text: 'A complex scalar has no N: nothing makes some graphs dominate. Its mean field is ⟨φ⟩ = 0 for λ > 0, and its graphs never become a geometry: the rank of the field is what turns graphs into spaces.' }));
    if (L?.kind === 'matrix') {
      body.push(el('p', { class: 'lead-text', text: `At large N only planar graphs survive (genus 0, N²); the eigenvalues of M settle into a density (Brézin, Itzykson, Parisi and Zuber 1978). ${L.potential ? `With ${L.potential}, ` : ''}at g = ${number(L.g, 3)}, a² = ${number(L.a2, 4)}.` }),
        el('div', { class: 'charts' },
          el('figure', {}, xyChart([{ x: L.density.x, y: L.density.rho, colour: 'rose' }], { xlabel: 'eigenvalue λ', ylabel: 'ρ(λ)' }), el('figcaption', { text: 'the eigenvalue density' })),
          el('figure', {}, xyChart([{ x: L.free_energy.g, y: L.free_energy.E0, colour: 'lilac' }], { xlabel: 'coupling g', ylabel: 'E₀(g)', vlines: [{ x: L.critical.g_c, label: `g_c = ${number(L.critical.g_c, 4)}` }] }),
            el('figcaption', { text: `the planar free energy; near g_c it is singular as (g − g_c)²⁻ᵞ with γ = ${number(L.critical.gamma, 3)}: the continuum limit, pure two-dimensional quantum gravity` }))));
      if (L.series?.length) body.push(el('p', { class: 'fact', text: `E₀ = Σ cₖ gᵏ: ${L.series.slice(1, 7).map((c, i) => `c${'₁₂₃₄₅₆'[i]} = ${exact(c, 5)}`).join(', ')}, …; the ratio of successive coefficients tends to 1/g_c.` }));
    } else if (L?.kind === 'melonic') {
      body.push(el('p', { class: 'lead-text', text: 'At large N only melonic graphs survive (degree ω = 0); their two-point function obeys a closed equation, the sum of all melons (Bonzom, Gurau, Riello and Rivasseau 2011). It ends at a critical coupling where the graphs grow large: branched polymers.' }),
        el('div', { class: 'charts' }, el('figure', {}, xyChart([{ x: L.lambda, y: L.G, colour: 'rose' }], { xlabel: 'coupling λ', ylabel: 'G(λ)', vlines: [{ x: L.critical.lambda_c, label: `λ_c = ${number(L.critical.lambda_c, 4)}` }] }),
          el('figcaption', { text: `the melonic two-point function; near λ_c, G_c − G ∝ √(λ_c − λ), γ = ${number(L.critical.gamma, 3)}` }))));
      if (L.series?.length) body.push(el('p', { class: 'fact', text: `Its coefficients (rooted melonic graphs, Fuss–Catalan): ${L.series.slice(0, 8).map((c) => exact(c)).join(', ')}, …` }));
    } else if (L?.kind === 'vector') {
      body.push(el('p', { class: 'lead-text', text: 'At large N the cactus graphs (bubbles on bubbles) dominate and resum into the gap equation, a self-consistent propagator. No geometry: a vector\'s graphs are trees of bubbles.' }),
        el('div', { class: 'charts' }, el('figure', {}, xyChart([{ x: L.coupling, y: L.gap, colour: 'rose' }], { xlabel: 'coupling', ylabel: 'G' }), el('figcaption', { text: 'the solution of the gap equation' }))));
    } else if (L?.kind === 'condensate' || t.family === 'GFT') {
      body.push(...condensateBody());
    }
    return section('large-n', 4, t.family === 'GFT' ? 'The condensate' : 'Large N', ...body);
  }

  function condensateBody() {
    const c = g.cond, out = [];
    out.push(el('p', { class: 'lead-text', text: 'Many quanta of the group field theory in one state: a condensate, a mean field σ_j(φ) for each spin j, in the relational time φ of a massless scalar field. Its volume V(φ) = Σ_j V_j |σ_j|² obeys an effective Friedmann equation: classical at large volume, with a bounce where the matter density reaches a critical value, instead of the big bang (Oriti, Sindoni and Wilson-Ewing 2016).' }));
    const rows = el('table', { class: 'data spins' }, el('tr', {}, el('th', { text: '2j' }), el('th', { text: 'Q (its charge)' }), el('th', { text: 'E (its energy)' }), el('th', { text: '' })));
    c.spins.forEach((s, i) => {
      const num = (key, step) => { const input = el('input', { type: 'number', value: s[key], step, style: 'width: 80px', oninput: () => { s[key] = Number(input.value); } }); return input; };
      rows.append(el('tr', {}, el('td', {}, num('two_j', 1)), el('td', {}, num('Q', 0.1)), el('td', {}, num('E', 0.1)),
        el('td', {}, c.spins.length > 1 ? el('button', { class: 'chip', onclick: () => { c.spins.splice(i, 1); render(); } }, 'remove') : null)));
    });
    const G = el('input', { type: 'number', value: c.G, step: 0.1, style: 'width: 70px', oninput: () => { c.G = Number(G.value); } });
    const p0 = el('input', { type: 'number', value: c.phi[0], step: 0.1, style: 'width: 70px', oninput: () => { c.phi[0] = Number(p0.value); } });
    const p1 = el('input', { type: 'number', value: c.phi[1], step: 0.1, style: 'width: 70px', oninput: () => { c.phi[1] = Number(p1.value); } });
    out.push(rows, el('div', { class: 'row' },
      el('button', { class: 'chip', onclick: () => { c.spins.push({ two_j: 2, Q: 1, E: 0 }); render(); } }, 'add a spin'),
      el('span', { class: 'note', text: 'G' }), G, el('span', { class: 'note', text: 'φ from' }), p0, el('span', { class: 'note', text: 'to' }), p1,
      el('button', { class: 'button primary', disabled: g.condRunning ? true : null, onclick: runCondensate }, g.condRunning ? 'Evolving…' : 'Evolve'),
      g.condError ? el('span', { class: 'error', text: g.condError }) : null));
    const r = g.condensate;
    if (r) {
      const b = r.bounce;
      out.push(el('div', { class: 'charts' },
        el('figure', {}, xyChart([{ x: r.phi, y: r.V, colour: 'rose' }, { x: r.phi, y: r.classical.V, colour: 'faint', dash: '5 4' }],
          { xlabel: 'relational time φ', ylabel: 'V(φ)', logy: true, points: b ? [{ x: b.phi, y: b.V, label: 'bounce' }] : [] }),
        chartLegend([{ label: 'the condensate', colour: 'rose' }, { label: 'classical FLRW, V ∝ exp(√(12πG) φ)', colour: 'faint', dash: '5 4' }]),
        el('figcaption', { text: 'the volume of the universe: the classical one vanishes in the past; the condensate\'s bounces' })),
        el('figure', {}, xyChart([{ x: r.friedmann.rho, y: r.friedmann.H2, colour: 'lilac' }, { x: r.friedmann.rho, y: r.friedmann.classical_H2, colour: 'faint', dash: '5 4' }],
          { xlabel: 'matter density ρ', ylabel: '(V′/3V)²', logx: true, vlines: b ? [{ x: b.rho_c, label: 'ρ_c' }] : [] }),
        chartLegend([{ label: 'effective Friedmann', colour: 'lilac' }, { label: 'classical, 4πG/3', colour: 'faint', dash: '5 4' }]),
        el('figcaption', { text: 'the effective Friedmann equation: classical at low density, zero at the critical density' }))));
      if (b) out.push(el('p', { class: 'fact', text: `Bounce at φ = ${number(b.phi, 4)}: V = ${number(b.V, 5)}, ρ = ${number(b.rho, 5)} = ρ_c.` }));
      else out.push(el('p', { class: 'fact', text: 'No bounce in this range of φ.' }));
    }
    return out;
  }

  function stageContinuum() {
    const c = continuumOf(g.theory, g.params);
    const body = [];
    if (!c) body.push(el('p', { class: 'note', text: 'A rank-0 or rank-1 theory makes no geometry at large N; a random planar quadrangulation (the matrix model\'s continuum) can be made here to compare.' }));
    else body.push(el('p', { class: 'lead-text', text: c.kind === 'quadrangulation'
      ? 'The planar graphs of the matrix model, taken at random and large, are random quadrangulations of the sphere; as they grow they converge to the Brownian map, a random surface of Hausdorff dimension 4 and spectral dimension 2: the continuum of two-dimensional quantum gravity (Le Gall 2013; Miermont 2013). Distances grow only as n^{1/4}, so a quadrangulation of a few thousand faces has a radius of about ten: the measured d_H rises toward 4 slowly with the size, while d_s is near 2 already.'
      : 'The melonic graphs, taken at random and large, are dual to branched polymers: tree-like spaces of Hausdorff dimension 2 and spectral dimension 4/3, not yet a smooth spacetime; finding a phase beyond them is the research of tensor models and group field theories (Gurau and Ryan 2014).' }));
    const kind = el('select', { onchange: () => { g.geo.kind = kind.value; } },
      ...[['quadrangulation', 'random planar quadrangulation'], ['melonic', 'random melonic graph']].map(([v, tx]) => el('option', { value: v, selected: (g.geo.kind || 'quadrangulation') === v ? true : null }, tx)));
    const size = el('input', { type: 'number', value: g.geo.size, min: 4, max: 20000, step: 50, style: 'width: 90px', oninput: () => { g.geo.size = Number(size.value); } });
    const seed = el('input', { type: 'number', value: g.geo.seed, min: 1, style: 'width: 70px', oninput: () => { g.geo.seed = Number(seed.value); } });
    body.push(el('div', { class: 'row' }, kind, el('span', { class: 'note', text: 'size' }), size, el('span', { class: 'note', text: 'seed' }), seed,
      el('button', { class: 'button primary', disabled: g.geoRunning ? true : null, onclick: runGeometry }, g.geoRunning ? 'Growing…' : 'Grow it'),
      g.geometry ? el('button', { class: 'button', onclick: () => onOpen(g.geometry, g.geometry.title || 'A random geometry of the large-N phase.') }, 'Open it in the complex views') : null,
      g.geoError ? el('span', { class: 'error', text: g.geoError }) : null));
    if (g.geometry) {
      const n = g.geometry;
      body.push(el('p', { class: 'fact', text: `${n.title || n.name}: ${n.vertices} vertices, ${n.edges.length} edges, ${(n.faces || []).length} faces.` }));
      const dims = el('div', { class: 'dims' });
      const expected = (g.geo.kind || c?.kind) === 'melonic' ? { ds: 4 / 3, dh: 2, label: '(branched polymers)' } : { ds: 2, dh: 4, label: '(Brownian map)' };
      renderDimensions(dims, { complex: n, result: g.dims, running: g.dimsRunning, error: g.dimsError, onRun: (graph) => runDims(graph), expected, compact: true });
      body.push(el('div', { class: 'continuum' }, geoHost, dims));
    }
    return section('continuum', 5, 'The continuum', ...body);
  }

  return {
    load,
    choose,
    render: () => { renderLeft(); render(); },
    shown: () => { if (geoView) geoView.resize(); },
    get theoryId() { return g.theory?.id; },
    get order() { return g.order; },
    get station() { return g.station; },
  };
}
